import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import React, { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

const clampOpts = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

interface RolodexFlipProps {
  items: string[];
  from?: number;
  interval?: number;
  flipDuration?: number;
  className?: string;
  style?: React.CSSProperties;
}

function RolodexFlipBase({
  items,
  from = 0,
  interval = 20,
  flipDuration = 10,
  className,
  style,
}: RolodexFlipProps) {
  const frame = useCurrentFrame();
  const sizer = items.reduce((a, b) => (b.length > a.length ? b : a), "");
  return (
    <span
      className={className}
      style={{
        position: "relative",
        display: "inline-block",
        perspective: 420,
        verticalAlign: "bottom",
        ...style,
      }}
    >
      <span style={{ visibility: "hidden" }}>{sizer}</span>
      {items.map((item, i) => {
        const inStart = from + (i - 1) * interval + flipDuration / 2;
        const outStart = from + i * interval;

        let rotate = 0;
        let y = 0;
        let opacity = 1;

        if (i > 0) {
          const pIn = interpolate(
            frame,
            [inStart, inStart + flipDuration],
            [0, 1],
            { ...clampOpts, easing: Easing.out(Easing.cubic) },
          );
          rotate = (1 - pIn) * -85;
          y = (1 - pIn) * 20;
          opacity = pIn;
        }
        if (i < items.length - 1) {
          const pOut = interpolate(
            frame,
            [outStart, outStart + flipDuration],
            [0, 1],
            { ...clampOpts, easing: Easing.in(Easing.cubic) },
          );
          rotate += pOut * 85;
          y -= pOut * 20;
          opacity *= 1 - pOut;
        }
        if (opacity <= 0.001) return null;

        return (
          <span
            key={`${i}-${item}`}
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              whiteSpace: "nowrap",
              opacity,
              transform: `translateY(${y}px) rotateX(${rotate}deg)`,
              transformOrigin: "50% 50%",
              backfaceVisibility: "hidden",
            }}
          >
            {item}
          </span>
        );
      })}
    </span>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  interval: {
    type: "number",
    min: 10,
    max: 40,
    step: 2,
    default: 20,
    description: "Interval",
    hiddenFromList: false,
  },
  flipDuration: {
    type: "number",
    min: 4,
    max: 20,
    step: 1,
    default: 10,
    description: "Flip duration",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["interval","flipDuration","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  interval: 20,
  flipDuration: 10,
  speed: 1,
};

type RolodexFlipElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof RolodexFlipBase>;

const RolodexFlipInner = forwardRef<
  HTMLDivElement,
  RolodexFlipElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<RolodexFlip>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <RolodexFlipBase
          {...(componentProps as unknown as ComponentProps<typeof RolodexFlipBase>)}
        />
      </div>
    </Sequence>
  );
});

export const RolodexFlip = Interactive.withSchema({
  Component: RolodexFlipInner,
  componentName: "<RolodexFlip>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
